EXPORT ZZT_INV() BEGIN
DIMGROB_P(G1,7,7,#123456h);
LOCAL accepted:=1, res:=0, x,y, pixels:={};
IFERR res:=INVERT_P(G1,3,2,3,2); THEN accepted:=0; END;
FOR y FROM 0 TO 6 DO FOR x FROM 0 TO 6 DO
 pixels:=CONCAT(pixels,{B→R(GETPIX_P(G1,x,y))});
END;END;
RETURN {accepted,res,pixels};
END;

